float gear(vec3 p,float r) {
    float n = 8.;
    p = radialRepeat(p,n);
        return max(min(roundBox(p,vec3(0,0,.005),r*.4),roundBox(p-vec3(r*.1,0,0),vec3(r*.08,r*.02,.005),.01)),-roundBox(p,vec3(0,0,.1),r*.3));
}
float arctan(float a, float b) {
    if (a*a+b*b==0.) return 0.;
    else return atan(a,b);
}
vec4 map(vec3 p) {
    vec3 o = p;
    vec3 q = p;
    float d = 1e9;
    float n = 30.;


    q = vec3(length(p),arctan(p.y,p.x),arctan(length(p.xy),p.z));

    float x = round(q.z/3.14159*n/2.);
    q.z = x/n*3.14159*2.;
    x = n-4.*abs(x-.25*n)+2.;
    float y = round(q.y/3.14159/2.*x);
    q.y = y/x*3.14159*2.;

    q.x = min(floor(q.x*20.),5.)/20.;

    vec3 w = q.x*vec3(vec2(cos(q.y),sin(q.y))*sin(q.z),cos(q.z));


    float s = sign(mod(x,2.)-.5);
    if (x>2.)
    s *= sign(mod(y,2.)-.5);
    p -= w;
    p.xy *= ei(q.y);
    p.xz *= ei(-q.z);
    //p.yz *= ei(q.z);
    p.xy *= ei(s*iTime+(.5+.5*s));
    d = gear(p,.8*q.x);
    return vec4(d,p);
}
vec3 normal (vec3 p) {
    vec2 e = vec2(1e-4,0);
    float m = map(p).x;
    return normalize(vec3(
        map(p+e.xyy).x-m,
        map(p+e.yxy).x-m,
        map(p+e.yyx).x-m
    ));

}
